{"command":["bash","-lc","python - <<'PY'
import json, glob, os, collections
base='alerts'
alerts=[]
for f in sorted(glob.glob(os.path.join(base,'alerts_at_*.json'))):
    data=json.load(open(f))
    for a in data:
        if a.get('state')!='firing':
            continue
        ns=a['labels'].get('namespace')
        if ns=='otel-demo':
            alerts.append(a)
print('Total firing alerts in otel-demo:', len(alerts))
# summarize by alertname
cnt=collections.Counter([a['labels'].get('alertname') for a in alerts])
for name,c in cnt.most_common():
    print(name,c)
PY"],"workdir":"/root/projects/open_source/zero/B96DF826-4BB2-4B62-97AB-6D84254C53D7/Scenario-83"}

